response_schema.schema:
{
    "prompt_id": "stage-XX-name",
    "status": "success | partial | failed",
    "runtime_logs": {
        "started_at": "ISO8601",
        "completed_at": "ISO8601",
        "duration_ms": 0,
        "workflow_steps": ["COMPREHEND", "ANALYZE", "..."],
        "decisions": [],
        "assumptions": [],
        "warnings": [],
        "errors": [],
        "validation": {
            "passed": true,
            "checks": [
                {"name": "", "passed": true, "message": ""}
            ]
        }
    },
    "sources_used": [
        {
            "url": "string - Full URL of the source",
            "title": "string - Title or description of source",
            "type": "search | fetch | api | cache",
            "data_extracted": ["string - What information was taken from this source"]
        }
    ],
    "meta_reasoning": {
        "comprehend": "string - How the input was interpreted",
        "analyze": "string - Key patterns and insights discovered",
        "strategize": "string - Approach chosen and why",
        "plan": "string - Action sequence created",
        "execute": "string - What was done and decisions made",
        "self_check": "string - Validation results and issues found",
        "refine": "string - Improvements made without scope expansion",
        "reconcile": "string - Handoff preparation and format verification",
        "synthesize": "string - How findings were combined into coherent output",
        "critical_choices": [
            {
                "choice": "string - What was decided",
                "alternatives": ["string - Other options considered"],
                "rationale": "string - Why this choice was made"
            }
        ]
    },
    "executive_summary": {
        "primary_finding": "string - The ONE most important discovery",
        "key_insights": ["string - 3-5 critical takeaways"],
        "confidence_level": "high | medium | low",
        "confidence_rationale": "string - Why this confidence level"
    },
    "output": {
        // Stage-specific data - schema defined per stage
    },
    "next_stage_guidance": {
        "priority_areas": ["string - What the next stage should focus on"],
        "watch_items": ["string - Potential issues to monitor"],
        "data_quality_notes": ["string - Any caveats about the data provided"]
    },
    "handoff": {
        "ready": true,
        "next_stage": "stage-XX-name",
        "missing_for_next": []
    },
    "extras": {
        // Optional catch-all for any additional stage-specific data
        // that doesn't fit the standard fields above.
        // Use descriptive keys. Examples:
        // "competitor_deep_dive": {...},
        // "alternative_approaches": [...],
        // "raw_search_results": [...],
        // "methodology_notes": "..."
    }
}
